@Override
public Collection<String> deserialize(JsonParser p, DeserializationContext ctxt,
        Collection<String> result)
    throws JacksonException
{
    // Ok: must point to START_ARRAY
    if (!p.isExpectedStartArrayToken()) {
        return handleNonArray(p, ctxt, result);
    }

    if (_valueDeserializer != null) {
        return deserializeUsingCustom(p, ctxt, result, _valueDeserializer);
    }
    try {
        while (true) {
            // First the common case:
            String value = p.nextStringValue();
            if (value != null) {
                result.add(value);
                continue;
            }
            JsonToken t = p.currentToken();
            if (t == JsonToken.END_ARRAY) {
                break;
            }
            if (t == JsonToken.VALUE_NULL) {
                if (_skipNullValues) {
                    continue;
                }
            } else if (t == JsonToken.START_ARRAY) {
                // [databind#2124]: Support for empty array coercion to null String
                JsonToken nextToken = p.nextToken();
                if (nextToken == JsonToken.END_ARRAY) {
                    CoercionAction act = _findCoercionFromEmptyArray(ctxt);
                    if (act == CoercionAction.AsNull || act == CoercionAction.TryConvert) {
                        value = null;
                    } else if (act == CoercionAction.AsEmpty) {
                        // Since we are using default/standard deserialization (not
                        // custom) one, can hard-code empty String
                        value = "";
                    } else {
                        // Fail case: delegate to _parseString which will throw proper error
                        value = _parseString(p, ctxt, _nullProvider);
                    }
                } else {
                    // Non-empty array: delegate to _parseString which will throw proper error
                    value = _parseString(p, ctxt, _nullProvider);
                }
            } else {
                value = _parseString(p, ctxt, _nullProvider);
            }

            if (value == null) {
                value = (String) _nullProvider.getNullValue(ctxt);

                if (value == null && _skipNullValues) {
                    continue;
                }
            }

            result.add(value);
        }
    } catch (Exception e) {
        throw DatabindException.wrapWithPath(ctxt, e,
                new JacksonException.Reference(result, result.size()));
    }
    return result;
}

private Collection<String> deserializeUsingCustom(JsonParser p, DeserializationContext ctxt,
        Collection<String> result, final ValueDeserializer<String> deser) throws JacksonException
{
    try {
        while (true) {
            /* 30-Dec-2014, tatu: This may look odd, but let's actually call method
             *   that suggest we are expecting a String; this helps with some formats,
             *   notably XML. Note, however, that while we can get String, we can't
             *   assume that's what we use due to custom deserializer
             */
            String value;
            if (p.nextStringValue() == null) {
                JsonToken t = p.currentToken();
                if (t == JsonToken.END_ARRAY) {
                    break;
                }
                // Ok: no need to convert Strings, but must recognize nulls
                if (t == JsonToken.VALUE_NULL) {
                    if (_skipNullValues) {
                        continue;
                    }
                    value = null;
                } else {
                    value = deser.deserialize(p, ctxt);
                }
            } else {
                value = deser.deserialize(p, ctxt);
            }

            if (value == null) {
                value = (String) _nullProvider.getNullValue(ctxt);

                if (value == null && _skipNullValues) {
                    continue;
                }
            }

            result.add(value);
        }
    } catch (Exception e) {
        throw DatabindException.wrapWithPath(ctxt, e,
                new JacksonException.Reference(result, result.size()));
    }
    return result;
}

